// Kelley Road CMS theme.
//
// Same shape as the OpenCMS default theme, but derived from the site brand so
// the admin reads as part of the same website. Written here rather than by
// editing modules/opencms/core/theme--default-cms.ts, which is shared plugin
// code kept in sync across sites — config/opencms--theme.ts is the swap point.

import type { CmsTheme } from "../../modules/opencms/core/theme--default-cms";
import brand from "../brand";

const theme: CmsTheme = {
  /* Charcoal carries primary weight; gold is the hover, matching the site
     button system where a dark button warms to gold. Tints derived from
     `primary` (e.g. `${primary}14`) land as soft neutral greys, not colour. */
  primary: brand.colors.primary,
  primaryHover: brand.colors.accent,

  sidebar: brand.colors.background,
  background: brand.colors.backgroundAlt,
  text: brand.colors.text,
  textMuted: brand.colors.textMuted,
  border: brand.colors.border,

  /* Semantic, not brand — destructive actions stay red. */
  danger: "#DC2626",

  sidebarWidth: 240,
  logoWidth: 160,
  contentPadding: 36,
  cardRadius: 14,
  cardPadding: 24,
};

export default theme;
